import hashlib
def pos(s): return int(hashlib.md5(s.encode()).hexdigest(), 16)
nodes = {"n1": pos("n1"), "n2": pos("n2"), "n3": pos("n3")}
ring = sorted(nodes.values())
def owner(key):
    p = pos(key)
    for r in ring:
        if r >= p: return [n for n, q in nodes.items() if q == r][0]
    return [n for n, q in nodes.items() if q == ring[0]][0]
for k in ["rec1", "rec2", "rec3"]:
    print(k, "->", owner(k))

